"""Debates (décima primeira leva, lacunas apontadas pela comparação com SEP e IEP): perdão, terrorismo, reparações históricas,
deveres das empresas, publicidade e manipulação, apostas, vacinação obrigatória, obra e artista."""
SEP = 'https://plato.stanford.edu/entries/'
WE = 'https://en.wikipedia.org/wiki/'
VP = 'Vida pessoal e relações'
JE = 'Justiça e Estado'
RS = 'Riqueza e sociedade'
LD = 'Liberdade e dano'
CO = 'Cotidiano'

DEBATES11 = [
dict(s='perdao', n='Perdoar é um dever?', t=VP, r='Perdoar quem não se arrependeu, perdoar em nome de outros, perdoar o imperdoável. O que o perdão é, quando é devido e quando é uma traição à vítima.',
 v='Perdoar é abrir mão do ressentimento e da cobrança contra quem nos fez mal, sem negar que o mal foi feito. Quase todas as tradições o elogiam; a filosofia pergunta se ele pode ser exigido, se depende do arrependimento do outro, e se há atos que não se devem perdoar. O tema cruza a ética das emoções (o ressentimento tem valor?), a justiça (perdoar cancela a punição?) e o cuidado de si (perdoar liberta quem perdoa?).',
 lados=[('O perdão é uma virtude, às vezes um dever', ['Tradições religiosas (o cristianismo acima de todas, mas também o budismo e o judaísmo com condições) fazem do perdão um dever: quem foi perdoado deve perdoar, e o ressentimento corrói quem o guarda.', 'Bem de quem perdoa: a psicologia mostra que o ressentimento prolongado faz mal a quem o sente; perdoar é, entre outras coisas, parar de dar ao agressor o poder de ocupar a mente da vítima.', 'Relações: sem perdão, nenhuma relação duradoura sobrevive, porque todos falham; o perdão é o que permite recomeçar sem fingir que nada aconteceu.', 'Paz coletiva: comissões de verdade e reconciliação (África do Sul) mostraram que sociedades que trocam parte da punição por verdade e perdão podem sair de conflitos que a vingança perpetuaria.']),
        ('O perdão é um dom, não um dever, e tem condições', ['Perdoar é prerrogativa da vítima: ninguém pode perdoar em nome de outro, e exigir o perdão da vítima é uma segunda violência (Jean Améry, sobrevivente de Auschwitz, defendeu o direito ao ressentimento).', 'Sem arrependimento, perdoar pode ser condescendência: trata o agressor como alguém de quem não se espera melhor, e deixa a injustiça sem resposta (Jeffrie Murphy).', 'O ressentimento tem valor moral: é a emoção que reconhece que fomos tratados como menos do que somos; abrir mão dele cedo demais é desrespeitar a si mesmo.', 'Há o imperdoável: para Jankélévitch, certos crimes excedem o que o perdão pode abranger; Derrida respondeu que só o imperdoável pede de fato perdão, e que isso o torna impossível e necessário ao mesmo tempo.'])],
 c=['Perdão e punição são coisas diferentes: a vítima pode perdoar e o Estado punir, ou a vítima não perdoar e o Estado aplicar a pena justa. O perdão cancela o ressentimento, não a justiça.', 'A distinção entre perdoar (o que só a vítima faz) e deixar de odiar (o que qualquer um pode fazer por si) resolve parte do debate: o segundo pode ser um dever para consigo; o primeiro, não é exigível de ninguém.', 'Perdão condicional (ao arrependimento) e incondicional (como dom) não se excluem: o primeiro é o padrão das relações justas; o segundo é supererrogatório, admirável e não devido.'],
 p=('parcial', 'O peso está com tratar o perdão como dom e virtude, não como dever exigível: só a vítima pode perdoar, ninguém tem direito ao perdão dela, e o ressentimento tem um valor moral que não se deve apagar sob pressão. Ao mesmo tempo, abrir mão do ódio quando ele só corrói, perdoar quem se arrependeu e reparou, e preferir a reconciliação à vingança são disposições que quase todas as teorias elogiam, e que fazem bem a quem as cultiva. O perdão não cancela a justiça; corre em paralelo a ela.'),
 teorias=[('etica-das-virtudes', 'Virtudes', 'O perdão é a virtude entre o rancor e a complacência; o virtuoso sabe quando e a quem.'), ('deontologia-kantiana', 'Kant', 'O ressentimento reconhece a dignidade violada; perdoar sem arrependimento pode desrespeitá-la.'), ('utilitarismo-classico', 'Utilitarismo', 'Perdoe quando reduz sofrimento (o seu, o do outro, o do ciclo de vingança); não quando encoraja o dano.'), ('etica-do-cuidado', 'Cuidado', 'As relações exigem reparação e recomeço; o perdão é parte do cuidado, não uma renúncia.'), ('etica-budista', 'Budismo', 'O ressentimento é veneno que se bebe esperando que o outro adoeça; soltar é compaixão por si e pelo outro.'), ('teoria-do-mandamento-divino', 'Mandamento divino', 'Perdoar é dever para quem foi perdoado por Deus; a tradição varia quanto às condições.')],
 licoes=['emocoes-morais', 'etica-do-cuidado', 'eticas-religiosas', 'aristoteles-e-as-virtudes'],
 fx=[('Forgiveness (Stanford Encyclopedia)', SEP + 'forgiveness/'), ('Forgiveness and Mercy', 'https://www.google.com/search?tbm=bks&q=Murphy+Hampton+Forgiveness+and+Mercy'), ('Além do Culpa e Expiação', 'https://www.google.com/search?tbm=bks&q=Jean+Am%C3%A9ry+Al%C3%A9m+do+Crime+e+Castigo'), ('Truth and Reconciliation Commission (Wikipédia)', WE + 'Truth_and_Reconciliation_Commission_(South_Africa)')]),

dict(s='terrorismo', n='Terrorismo: há alguma versão justificável?', t=JE, r='Matar civis para aterrorizar e forçar uma mudança política. A definição, a diferença para a guerra e para a resistência, e por que a resposta quase unânime é não.',
 v='Terrorismo é o uso da violência contra civis, ou a ameaça dela, para espalhar medo e obter um fim político. A definição é disputada porque quem a usa quer excluir a própria causa; mas o núcleo (civis como alvo, o medo como meio) é o que a maioria dos filósofos adota. A pergunta ética é se alguma causa, por mais justa, pode autorizar esse meio, e o que diferencia o terrorismo da guerra, que também mata civis, e da resistência armada contra tiranias.',
 lados=[('Nunca é justificável', ['Usa pessoas inocentes como meio: a vítima é escolhida justamente porque não tem relação com a disputa, para que o medo atinja todos. É o caso mais puro de tratar alguém como instrumento.', 'A teoria da guerra justa, que admite matar em combate, proíbe atacar civis deliberadamente; o terrorismo é essa proibição invertida: o civil é o alvo, não o dano colateral.', 'Consequências: o terrorismo raramente obtém o que busca e quase sempre fortalece quem combate, endurece o adversário e destrói a legitimidade da causa que o adota; a evidência histórica é ampla.', 'Se admitido para uma causa justa, o argumento serve a qualquer causa que se creia justa: quem decide que a sua é a exceção?']),
        ('Argumentos que já foram oferecidos a favor', ['Emergência suprema (Walzer sobre o bombardeio de cidades alemãs em 1940–41): quando a derrota significaria o extermínio de um povo e não há outro meio, a proibição cederia. O próprio Walzer limitou o caso e o considerou uma mancha moral, não uma licença.', 'Simetria: Estados matam civis em bombardeios “colaterais” sabendo que vão morrer; chamar de terrorismo só a violência dos fracos é hipocrisia (Chomsky, Honderich). O argumento mostra que o terrorismo de Estado existe, não que o dos grupos seja aceitável.', 'Último recurso de quem não tem exército: povos sob ocupação ou tirania não têm outro meio de lutar. A resposta é que há meios (resistência contra alvos militares, desobediência, sabotagem) e que a escolha de civis como alvo não é imposta pela fraqueza, é escolhida.'])],
 c=['A simetria é um argumento forte contra a hipocrisia e nulo como justificação: se o bombardeio deliberado de civis por Estados é terrorismo, ele é condenado pelo mesmo princípio, e não absolve ninguém.', 'A exceção da emergência suprema, mesmo aceita, é estreita a ponto de quase não existir: exige a iminência de um mal comparável ao genocídio e a ausência real de alternativas, e seus defensores a tratam como tragédia, não como direito.', 'A definição importa: resistência armada contra alvos militares de um regime ilegítimo não é terrorismo, e chamá-la assim é a estratégia dos regimes. O que define o terrorismo é o alvo (civis) e o método (o medo), não a causa.'],
 p=('forte', 'A razão pesa claramente contra: atacar civis deliberadamente para espalhar medo é condenado por todas as grandes teorias, do consequencialismo (que raramente vê bons resultados nele e vê muitos maus) à deontologia (que o toma como o exemplo mais puro de usar pessoas como meio) e à teoria da guerra justa (que o proíbe mesmo em guerras justas). A única exceção discutida com seriedade, a emergência suprema de Walzer, é tão estreita que seus defensores a chamam de mancha e não de licença. O que o debate deixa aberto é o uso do rótulo: o terrorismo de Estado é terrorismo, e a resistência contra alvos militares não é.'),
 teorias=[('deontologia-kantiana', 'Kant', 'Usar a morte de inocentes como mensagem é tratar pessoas como meros meios, sem exceção.'), ('deontologia-absolutista', 'Absolutismo', 'Matar inocentes deliberadamente nunca é permitido, qualquer que seja o fim.'), ('deontologia-de-limiar', 'Deontologia de limiar', 'A proibição cede só em catástrofe iminente e comprovada; é a estrutura da emergência suprema.'), ('utilitarismo-classico', 'Utilitarismo', 'Em quase todos os casos reais, o terrorismo produz mais sofrimento e nenhum ganho; a conta condena.'), ('contratualismo-escanloniano', 'Scanlon', 'Nenhum civil poderia aceitar um princípio que o torne alvo legítimo por conveniência de uma causa.'), ('doutrina-do-duplo-efeito', 'Duplo efeito', 'Distingue o civil atingido sem intenção do civil escolhido como alvo; o terrorismo está do lado proibido.')],
 licoes=['direitos-e-limiares', 'intencao-e-previsao', 'catastrofes-morais', 'da-etica-a-politica'],
 fx=[('Terrorism (Stanford Encyclopedia)', SEP + 'terrorism/'), ('War (Stanford Encyclopedia)', SEP + 'war/'), ('Just and Unjust Wars', 'https://www.google.com/search?tbm=bks&q=Walzer+Just+and+Unjust+Wars'), ('Definition of terrorism (Wikipédia)', WE + 'Definition_of_terrorism')]),

dict(s='reparacoes-historicas', n='Reparações históricas: quem deve o quê a quem?', t=JE, r='Escravidão, colonização, genocídios. Os vivos devem reparar o que os mortos fizeram? A quem se paga, e com que dinheiro?',
 v='A escravidão no Brasil durou mais de três séculos e seus efeitos (renda, patrimônio, violência, representação) são mensuráveis hoje. O mesmo vale para a colonização e para povos indígenas. A pergunta das reparações é se os descendentes dos beneficiados e o Estado devem algo aos descendentes das vítimas, e em que forma: dinheiro, terra, políticas, reconhecimento. É um dos debates em que a filosofia moral e a política se encontram com mais atrito.',
 lados=[('A favor', ['Enriquecimento sem causa: a riqueza acumulada pela exploração passou por herança e instituições para quem vive hoje; quem herda o ganho herda a dívida, como herda dívidas junto com bens.', 'Injustiça contínua: não é um dano do passado, e sim uma estrutura que ainda distribui desvantagem (Young); a reparação não paga pelos mortos, corrige o que os vivos ainda sofrem.', 'Precedentes: a Alemanha indenizou vítimas do nazismo; os Estados Unidos indenizaram nipo-americanos internados; o Brasil indenizou perseguidos da ditadura. A diferença da escravidão é de escala e de tempo, não de princípio.', 'Reconhecimento: parte do dano é simbólico; a reparação diz publicamente que houve injustiça e quem foi a vítima, e isso tem valor próprio.']),
        ('Contra ou com reservas', ['Responsabilidade é pessoal: ninguém vivo escravizou ninguém; punir descendentes por atos de antepassados viola o princípio de que se responde pelo que se fez (Nozick admite a retificação, mas exige a cadeia de injustiça identificável).', 'Problema da não identidade (Parfit): sem a escravidão, os descendentes atuais não existiriam; não se pode dizer que foram prejudicados por aquilo sem o qual não existiriam. A resposta usual é que a reparação é pela desvantagem presente, não pela existência.', 'Quem paga e quem recebe: populações misturadas, imigração posterior, pobres entre os “devedores”; a conta exata é impossível, e a aproximação pode criar novas injustiças.', 'Preferir o futuro ao passado: políticas universais contra a pobreza e a discriminação atingem os mesmos beneficiários sem a disputa sobre a dívida histórica, e com mais apoio político.'])],
 c=['A objeção da responsabilidade pessoal é forte contra a culpa e fraca contra a obrigação institucional: o Estado que legalizou a escravidão é o mesmo Estado, e instituições respondem por seus atos passados como respondem por suas dívidas.', 'O problema da não identidade é resolvido deslocando o objeto: repara-se a desvantagem que as pessoas existentes sofrem agora por efeito da estrutura, e isso não depende de quem teria existido sem ela.', 'A forma da reparação importa mais do que o rótulo: a maioria das propostas sérias é de políticas (educação, terra, patrimônio, saúde) direcionadas, mais reconhecimento oficial, e não de cheques individuais.'],
 p=('parcial', 'O peso está com reconhecer uma obrigação de reparação, com uma condição: ela se fundamenta melhor na injustiça que continua a produzir desvantagem hoje, e na responsabilidade de instituições que persistem, do que na culpa pessoal de descendentes, que ninguém defende. As objeções mais fortes não negam o dever; disputam a forma, e aí a resposta que mais convence é políticas direcionadas somadas a reconhecimento público, em vez de pagamentos individuais de cálculo impossível. O debate continua aberto sobre o quanto, o como e até quando.'),
 teorias=[('deontologia-de-direitos', 'Direitos (Nozick)', 'A retificação de injustiças passadas é um princípio de justiça; a dificuldade é a cadeia de prova.'), ('contratualismo-rawlsiano', 'Rawls', 'Sob o véu, ninguém aceitaria herdar desvantagem por crimes contra seus antepassados.'), ('prioritarismo', 'Prioritarismo', 'Quem está pior tem prioridade, e a desvantagem herdada é parte do que o define.'), ('utilitarismo-classico', 'Utilitarismo', 'Julgue pelo que reduz mais sofrimento: políticas direcionadas eficazes, com ou sem o nome de reparação.'), ('etica-das-virtudes', 'Virtudes', 'A justiça inclui reconhecer o mal feito em nome da comunidade a que se pertence.'), ('ubuntu', 'Ubuntu', 'A pessoa se faz na comunidade; a comunidade repara o que fez para refazer-se.')],
 licoes=['igualdade-humana', 'responsabilidade-coletiva', 'etica-populacional', 'economia-politica-e-etica'],
 fx=[('Black Reparations (Stanford Encyclopedia)', SEP + 'black-reparations/'), ('Reparations for slavery (Wikipédia)', WE + 'Reparations_for_slavery'), ('Responsibility for Justice', 'https://www.google.com/search?tbm=bks&q=Iris+Marion+Young+Responsibility+for+Justice'), ('Anarquia, Estado e Utopia', 'https://www.google.com/search?tbm=bks&q=Nozick+Anarquia+Estado+e+Utopia')]),

dict(s='empresas-e-lucro', n='Empresas têm deveres além do lucro?', t=RS, r='Friedman contra Freeman: a empresa deve só aos acionistas ou a todos os afetados? O que a ética diz sobre o lucro, as regras do jogo e quem fica fora delas.',
 v='Milton Friedman escreveu em 1970 que a única responsabilidade social da empresa é aumentar o lucro dentro das regras do jogo. Edward Freeman respondeu que a empresa deve a todas as partes interessadas (stakeholders): trabalhadores, clientes, fornecedores, comunidade. A disputa parece de administração, mas é de ética: quem conta quando uma empresa decide, e quem decide pelos que não estão à mesa.',
 lados=[('Só o lucro, dentro das regras', ['Os executivos administram dinheiro alheio; gastá-lo em causas é tributar acionistas sem mandato. Quem quer fazer o bem faz com o próprio dinheiro.', 'Divisão de trabalho institucional: empresas produzem, Estados regulam e redistribuem; se cada empresa decidir o que é socialmente bom, decide sem legitimidade e sem competência.', 'O lucro, em mercados competitivos e bem regulados, já é o sinal de que a empresa serve a alguém; a busca de lucro criou mais bem-estar do que qualquer filantropia.', 'A “responsabilidade social” vira marketing e desvio: a empresa escolhe causas que vendem e esconde o que custa.']),
        ('Deveres com todos os afetados', ['A empresa é um ator moral: ela decide, prevê e causa; dizer que só deve aos donos é dizer que o dano a terceiros não conta, o que nenhuma teoria aceita para pessoas.', 'As regras do jogo são feitas em parte pelas próprias empresas (lobby, captura regulatória); quem escreve as regras não pode esconder-se atrás delas.', 'Externalidades: poluição, condições de trabalho e sofrimento animal não aparecem no preço; o lucro é alto justamente porque alguém paga fora da conta. Ser “eficiente” às custas de quem não tem voz não é mérito.', 'O próprio Friedman admitia a exceção das regras e da “honestidade”; o debate é sobre o que elas incluem.'])],
 c=['Os dois lados concordam mais do que parece: Friedman exige respeitar regras e evitar fraude; Freeman admite que sem lucro não há empresa. A disputa real é sobre o que a empresa deve quando a lei é omissa ou fraca, e sobre quem não tem voz.', 'A crítica mais forte ao modelo do lucro não é a de que ele ignore a sociedade, e sim a de que ele ignore quem está fora das regras: os animais criados industrialmente e as gerações futuras não têm lei que os proteja a contento, e a empresa que lucra sobre eles está dentro das regras e fora da ética.', 'A resposta institucional (regular melhor) e a resposta ética (a empresa deve agir bem mesmo sem regra) não competem: a primeira é a mais segura e a segunda é o que vale enquanto a primeira não chega.'],
 p=('parcial', 'O peso está com os deveres além do lucro, com uma precisão: a empresa é um agente moral que responde pelo dano que causa, e “dentro das regras” não basta onde as regras são fracas, capturadas ou inexistentes, como é o caso dos animais e do futuro. A posição de Friedman tem razão em dois pontos que sobrevivem: executivos não devem gastar dinheiro alheio em causas pessoais, e a regulação pública é o lugar mais legítimo para decidir o que a sociedade exige. A síntese defendida é: lucro como meio, não causar dano como limite, e regras melhores como meta.'),
 teorias=[('consequencialismo-de-regras', 'Consequencialismo de regras', 'Julgue o sistema: empresas que internalizam os danos produzem mais bem-estar do que as que os exportam.'), ('deontologia-kantiana', 'Kant', 'Trabalhadores, clientes e vizinhos são fins; a empresa que os usa como meros meios age mal, lucre ou não.'), ('contratualismo-escanloniano', 'Scanlon', 'Um princípio que permita lucrar causando dano a quem não consentiu seria razoavelmente rejeitado pelos afetados.'), ('egoismo-etico', 'Egoísmo ético', 'Cada agente busca o próprio interesse dentro das regras; é a base filosófica mais próxima de Friedman.'), ('sencientismo', 'Sencientismo', 'As maiores vítimas das empresas são os animais, que nenhuma regra representa à mesa.'), ('etica-das-virtudes', 'Virtudes', 'Uma empresa tem caráter: honestidade, justiça com quem depende dela, prudência.')],
 licoes=['economia-politica-e-etica', 'exploracao', 'etica-animal-na-pratica', 'responsabilidade-coletiva'],
 fx=[('Business Ethics (Stanford Encyclopedia)', SEP + 'ethics-business/'), ('The Social Responsibility of Business Is to Increase Its Profits', 'https://www.nytimes.com/1970/09/13/archives/a-friedman-doctrine-the-social-responsibility-of-business-is-to.html'), ('Stakeholder theory (Wikipédia)', WE + 'Stakeholder_theory'), ('Strategic Management: A Stakeholder Approach', 'https://www.google.com/search?tbm=bks&q=Freeman+Strategic+Management+A+Stakeholder+Approach')]),

dict(s='publicidade-e-manipulacao', n='Publicidade e manipulação: onde persuadir vira enganar?', t=CO, r='Informar, seduzir, explorar vieses, mirar crianças. A linha entre a persuasão legítima e a manipulação, e por que ela é mais nítida do que parece.',
 v='A publicidade informa que um produto existe e tenta fazer com que se queira. O segundo passo é onde a ética entra: há diferença entre convencer com razões, seduzir com imagens e explorar um viés ou uma fraqueza. A tecnologia tornou a pergunta urgente: anúncios personalizados sabem quando a pessoa está vulnerável, e o desenho de aplicativos usa a psicologia do vício. O que separa a persuasão aceitável da manipulação?',
 lados=[('A publicidade é persuasão legítima', ['Adultos sabem que anúncios vendem; a desconfiança é parte do jogo, e tratar o consumidor como incapaz de resistir é paternalismo.', 'A publicidade financia mídia, cultura e serviços gratuitos; sem ela, muito do que existe seria pago ou não existiria.', 'A criação de desejos não é má em si: a arte, a amizade e a educação também criam desejos que não tínhamos; o problema seria só o desejo por coisas ruins.', 'A fronteira já existe na lei: fraude, propaganda enganosa e mira em crianças são proibidas; o resto é liberdade de expressão comercial.']),
        ('Grande parte da publicidade é manipulação', ['Manipular é influenciar contornando a razão da pessoa: medo, insegurança, comparação social, urgência fabricada, escassez falsa. Isso não é dar razões; é operar o mecanismo por fora (Cass Sunstein, Robert Noggle).', 'Personalização: um anúncio que aparece no momento de fraqueza detectado pelos dados (luto, dívida, dieta) não persuade, explora. A assimetria de informação e de poder é o que define a exploração.', 'Crianças e adolescentes não têm a defesa que o primeiro lado supõe; o desenho de jogos e redes para reter atenção usa os mesmos mecanismos do jogo de azar.', 'O custo coletivo: uma cultura inteira treinada para desejar o que não precisa e para medir-se por consumo tem efeitos sobre bem-estar, dívida e ambiente que nenhum anúncio individual mostra.'])],
 c=['A linha mais útil é a de Noggle: persuasão oferece razões, evidências ou apelos emocionais adequados ao caso; manipulação induz crenças falsas, emoções desproporcionais ou desejos que a pessoa não endossaria se visse o mecanismo. O teste prático: a técnica funcionaria se a pessoa soubesse exatamente como funciona?', 'O argumento da autonomia corta para os dois lados: proteger o adulto de toda influência o infantiliza; deixá-lo exposto a sistemas desenhados para vencer sua atenção o trata como presa.', 'Há consenso em três pontos: fraude é errada; mirar crianças com técnicas de manipulação é errado; e usar vulnerabilidade detectada por dados é exploração. O desacordo fica no meio: a sedução comum.'],
 p=('parcial', 'O peso está com distinguir persuasão de manipulação pelo mecanismo, não pela intenção de vender: oferecer razões e apelos adequados é legítimo, e contornar a razão por meio de vieses, insegurança fabricada ou vulnerabilidade detectada é manipulação, errada pelo que faz com a autonomia de quem a sofre. Sobre crianças e sobre o uso de dados pessoais para atingir momentos de fraqueza, há consenso de que a prática é inaceitável. A defesa da publicidade como persuasão legítima vale para a parte dela que passaria no teste de transparência: a que ainda funcionaria se o público soubesse como funciona.'),
 teorias=[('deontologia-kantiana', 'Kant', 'Manipular é contornar a razão do outro: usá-lo como meio mesmo que ele saia satisfeito.'), ('utilitarismo-classico', 'Utilitarismo', 'Some os efeitos: informação útil contra desejos induzidos, dívida e insatisfação crônica.'), ('contratualismo-escanloniano', 'Scanlon', 'Ninguém aceitaria um princípio que permita influenciá-lo por técnicas que ele rejeitaria se conhecesse.'), ('etica-das-virtudes', 'Virtudes', 'Honestidade de quem anuncia e temperança de quem compra; a publicidade manipuladora corrói as duas.'), ('egoismo-etico', 'Egoísmo ético', 'Cada um defende o próprio interesse, e o consumidor que não se defende tem o que merece; é a posição que o primeiro lado pressupõe.')],
 licoes=['vieses-morais', 'fraqueza-de-vontade', 'etica-da-tecnologia', 'kant-e-o-imperativo-categorico'],
 fx=[('The Ethics of Manipulation (Stanford Encyclopedia)', SEP + 'ethics-manipulation/'), ('Advertising (Wikipédia)', WE + 'Advertising'), ('Dark pattern (Wikipédia)', WE + 'Dark_pattern')]),

dict(s='apostas', n='Apostas: liberdade, vício e quem lucra com ele', t=LD, r='Apostas esportivas por celular, cassinos, loterias do Estado. Entre o direito de arriscar o próprio dinheiro e uma indústria desenhada para explorar a compulsão.',
 v='Apostar é arriscar dinheiro num resultado incerto. Como atividade entre adultos, parece assunto privado. Como indústria, é um sistema desenhado com a psicologia do vício: recompensas intermitentes, quase-vitórias, acesso permanente pelo celular, publicidade em jogos e redes. A pergunta ética é a do paternalismo: até onde o Estado deve proteger quem quer arriscar, e o que deve a indústria a quem ela sabe que vai perder.',
 lados=[('Liberdade de arriscar', ['O dinheiro é da pessoa; perder num jogo é como gastar em qualquer prazer. O princípio do dano de Mill protege o que só prejudica a si mesmo.', 'A maioria aposta pouco e por diversão; punir todos pela minoria compulsiva é injusto, e a proibição cria mercado clandestino sem nenhuma proteção.', 'Loterias e apostas legais financiam esporte, cultura e saúde; a regulação, não a proibição, é o modelo que funciona.', 'Paternalismo em escada: se o Estado proíbe apostar, por que não proíbe fumar, beber, comer mal?']),
        ('A indústria explora uma vulnerabilidade conhecida', ['O vício em jogo é um transtorno reconhecido; a indústria sabe que a maior parte do lucro vem da minoria compulsiva e desenha o produto para ela (limites fáceis de burlar, bônus, notificações). Não é oferecer uma escolha: é cultivar a perda de controle.', 'O dano não fica na pessoa: famílias endividadas, crianças sem o dinheiro da comida, suicídios. O “só prejudica a si mesmo” é falso para quem tem dependentes.', 'Publicidade e acesso: apostas no celular, anunciadas em jogos e redes, com influenciadores e patrocínio de clubes, atingem adolescentes e pobres com força desproporcional; a evidência de países que liberaram mostra aumento de dívida e de pedidos de ajuda.', 'Paternalismo brando (Sunstein e Thaler): limites de gasto, pausas obrigatórias, autoexclusão, proibição de bônus e de propaganda mantêm a liberdade de apostar e reduzem o dano; é o modelo de vários países europeus.'])],
 c=['O princípio do dano admite a regulação sem contradição: quando a atividade é desenhada para contornar a vontade (recompensa intermitente, acesso constante), a escolha que ela protege é a menos livre de todas; proteger a autonomia pode exigir limitar o produto, não a pessoa.', 'A objeção da escada (fumo, álcool) prova o oposto do que pretende: fumo e álcool são regulados, com restrição de publicidade e acesso, e a regulação reduziu o dano; apostas digitais ainda estão onde o cigarro estava nos anos 1960.', 'O Estado que lucra com a aposta tem conflito de interesse; a regulação precisa ser desenhada por quem não depende da receita.'],
 p=('parcial', 'O peso está com a regulação forte: a liberdade de arriscar o próprio dinheiro merece proteção, mas uma indústria que lucra sobretudo com a compulsão, desenha o produto para alimentá-la e anuncia a quem menos se defende não oferece escolha livre; o dano se espalha às famílias e cai com mais peso sobre os pobres. A posição mais defendida não é a proibição, que falhou onde foi tentada, e sim o paternalismo brando e a restrição de publicidade e acesso, no modelo que já se aplica ao fumo. O que fica aberto é quanto o Estado, sócio na receita, consegue regular a si mesmo.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo (Mill)', 'O princípio do dano protege a aposta privada e autoriza regular a indústria pelos danos a terceiros e pela perda de autonomia.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Compare regimes: proibição, liberação e regulação forte; a evidência favorece a última.'), ('deontologia-kantiana', 'Kant', 'Desenhar um produto para contornar a vontade de alguém é usá-lo como meio.'), ('prioritarismo', 'Prioritarismo', 'O dano concentra-se nos que já estão pior; isso pesa mais do que a diversão de quem pode perder.'), ('etica-das-virtudes', 'Virtudes', 'Temperança e prudência de quem aposta; justiça de quem oferece o jogo.'), ('deontologia-de-direitos', 'Direitos', 'Liberdade de usar o próprio dinheiro; restrições só pelo dano a outros.')],
 licoes=['fraqueza-de-vontade', 'probabilidade-e-etica', 'vieses-morais', 'da-etica-a-politica'],
 fx=[('Paternalism (Stanford Encyclopedia)', SEP + 'paternalism/'), ('Problem gambling (Wikipédia)', WE + 'Problem_gambling'), ('Nudge', 'https://www.google.com/search?tbm=bks&q=Thaler+Sunstein+Nudge'), ('Sobre a Liberdade', 'https://www.google.com/search?tbm=bks&q=Mill+Sobre+a+Liberdade')]),

dict(s='vacinacao-obrigatoria', n='Vacinação obrigatória: o corpo de um e o dano aos outros', t=LD, r='Exigir vacina para a escola, o trabalho ou a entrada em lugares. O que a ética da saúde pública diz sobre coerção, imunidade coletiva e o direito de recusar.',
 v='Vacinas protegem quem as toma e, por imunidade coletiva, quem não pode tomá-las: bebês, imunossuprimidos, idosos. Quando a cobertura cai, doenças controladas voltam. A pergunta é se o Estado pode exigir a vacinação, com que meios (multa, exclusão da escola, exigência para trabalho) e com que exceções. É um caso clássico do conflito entre a autonomia sobre o próprio corpo e o dano a terceiros.',
 lados=[('A obrigação é legítima', ['Princípio do dano: recusar a vacina não prejudica só a si; quem não se vacina pode transmitir a doença a quem não pode se proteger. A liberdade do corpo termina onde começa o corpo dos outros.', 'Carona: a imunidade coletiva é um bem público; quem a aproveita sem contribuir transfere o risco para os que contribuem, e exigir a parte de cada um é justiça, não tirania (o argumento do fair play).', 'Evidência: as vacinas de calendário têm risco minúsculo e benefício enorme, comprovados em décadas e bilhões de doses; a desproporção justifica a exigência onde a adesão voluntária não basta.', 'Precedentes aceitos: a vacinação obrigatória para escola existe em muitos países há um século, e eliminou a varíola, quase a pólio e, onde se mantém, o sarampo.']),
        ('A obrigação deve ser o último recurso', ['Integridade corporal: injetar algo no corpo de alguém contra a vontade é uma das invasões mais graves; o consentimento informado é o princípio central da bioética desde Nuremberg, e a exceção precisa de justificação muito forte.', 'A coerção custa confiança: campanhas obrigatórias mal conduzidas alimentam a desconfiança que tentam combater; informação, acesso fácil e exemplo costumam obter cobertura alta sem força (Revolta da Vacina, 1904).', 'Proporcionalidade: a obrigação depende da doença (gravidade, transmissibilidade), da vacina (eficácia contra transmissão, segurança) e da situação (surto ou não); uma regra única para todas não se justifica.', 'Exceções: contraindicações médicas são incontroversas; objeções religiosas e de consciência são disputadas, porque a imunidade coletiva não distingue a razão da recusa.'])],
 c=['O desacordo não é sobre o princípio (o dano a terceiros autoriza limitar a liberdade), e sim sobre o meio: entre informar, facilitar, incentivar, condicionar (escola, trabalho) e punir, a escada deve ser subida só quando o degrau anterior falhou (a “escada de intervenção” do Nuffield Council).', 'A objeção da integridade corporal é mais forte contra a vacinação forçada (fisicamente) do que contra a condicionada (sem vacina, sem escola): a segunda preserva a escolha e cobra o custo de quem a faz, e é a forma usada na prática.', 'A evidência decide muito: para doenças graves e vacinas que bloqueiam transmissão, a exigência é fácil de justificar; para vacinas que protegem só quem toma, o argumento do dano a terceiros enfraquece e sobra o paternalismo.'],
 p=('parcial', 'O peso está com a legitimidade da obrigação condicionada (vacina como requisito para escola, certas profissões e situações de surto), fundada no dano a terceiros e na justiça de contribuir para o bem público de que todos dependem; é a posição dominante na ética da saúde pública e a prática da maioria das democracias. A crítica acerta ao exigir proporcionalidade (doença, vacina, contexto), ao preferir informação e acesso antes da coerção, e ao reservar a força física para emergências extremas. As contraindicações médicas são exceção pacífica; as de consciência seguem em disputa.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo (Mill)', 'O dano a terceiros autoriza a exigência; o cálculo de risco e benefício a favorece de longe.'), ('contratualismo-rawlsiano', 'Rawls', 'Sob o véu, ninguém escolheria uma sociedade em que os vulneráveis dependem da boa vontade dos demais.'), ('deontologia-de-direitos', 'Direitos', 'O direito ao próprio corpo é forte, mas não inclui o de expor outros a uma doença evitável.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Regras de vacinação obrigatória para escola produziram a eliminação de doenças; a regra se justifica pelo histórico.'), ('deontologia-kantiana', 'Kant', 'A máxima “aproveito a imunidade dos outros sem contribuir” não pode ser universalizada.'), ('etica-das-virtudes', 'Virtudes', 'Solidariedade e prudência: vacinar-se é cuidar de quem não pode.')],
 licoes=['bioetica', 'etica-da-crenca', 'da-etica-a-politica', 'responsabilidade-coletiva'],
 fx=[('Public Health Ethics (Stanford Encyclopedia)', SEP + 'publichealth-ethics/'), ('Vaccination policy (Wikipédia)', WE + 'Vaccination_policy'), ('Public health: ethical issues (Nuffield Council on Bioethics)', 'https://www.nuffieldbioethics.org/publications/public-health'), ('Revolta da Vacina (Wikipédia)', 'https://pt.wikipedia.org/wiki/Revolta_da_Vacina')]),

dict(s='obra-e-artista', n='Separar a obra do artista?', t=CO, r='Ouvir, ler, assistir e pagar por obras de quem fez coisas terríveis. O que a ética diz sobre a obra, sobre o consumo e sobre o que muda quando o autor está vivo.',
 v='Um músico condenado por abuso, um cineasta foragido, um escritor que defendeu o indefensável. As obras existem e muitas são boas. Três perguntas se confundem no debate: a obra fica pior por causa do autor (uma questão de estética e ética da arte)? É errado consumi-la (uma questão de consequências e de cumplicidade)? E o que se deve fazer com o autor (uma questão de punição e de perdão)?',
 lados=[('Separar: a obra tem valor próprio', ['A obra é um objeto público que não pertence mais ao autor; seu valor está no que ela faz com quem a recebe. Julgá-la pelo autor é falácia genética: o erro de avaliar uma coisa pela origem.', 'Se a biografia desqualificasse a obra, perderíamos boa parte da arte da história: Caravaggio matou um homem, Wagner era antissemita, Céline colaborou com nazistas.', 'O consumo privado de uma obra de autor morto não beneficia ninguém que fez mal; ler Céline não paga nada a Céline.', 'O boicote como regra geral vira censura por biografia, com os excessos do cancelamento: quem decide qual pecado desqualifica?']),
        ('Não dá para separar sempre', ['Algumas obras são inseparáveis do mal: a comédia que ridiculariza as vítimas do próprio autor, o filme que encena o abuso que o diretor cometia, a obra que foi o instrumento. Aí a obra é parte do ato (Berys Gaut: a ética entra na estética quando a obra pede que se endosse o mal).', 'Autor vivo: comprar, assistir e aplaudir dá dinheiro, poder e plataforma a quem continua a causar dano, e sinaliza às vítimas que o talento compra impunidade. Isso é consequência, não falácia.', 'A experiência muda: saber o que o autor fez altera o que a obra significa para quem a recebe, e isso não é irracional; é parte de como arte e vida se tocam.', 'Há uma questão de atenção: dar espaço a quem fez mal é tirá-lo de quem não fez; o tempo e o dinheiro do público são finitos.'])],
 c=['As três perguntas têm respostas diferentes: a obra raramente fica pior por causa do autor (exceto quando o mal está nela); consumir obra de autor morto é quase sempre permitido; consumir e financiar obra de autor vivo que continua a causar dano é uma escolha com consequências reais, e cada um responde por ela.', 'A diferença entre apreciar e promover é a mais útil: ler o livro em casa e dar-lhe um prêmio ou um palco são atos diferentes, com públicos e efeitos diferentes.', 'Nenhuma das posições justifica destruir ou proibir obras; a disputa é sobre o que cada um escolhe apoiar, e sobre instituições (prêmios, festivais, escolas) que decidem o que celebrar.'],
 p=('parcial', 'O peso está com uma separação condicional: a obra tem valor próprio e o passado do autor não a apaga, salvo quando o mal faz parte dela; mas a decisão de consumir e, sobretudo, de financiar e celebrar o autor é um ato com consequências, que pesam mais quando ele está vivo, continua a causar dano ou se beneficia da plataforma. A posição mais defendida distingue apreciar (livre) de promover (responsável), e rejeita tanto o boicote automático por biografia quanto a ideia de que o talento isenta.'),
 teorias=[('utilitarismo-classico', 'Utilitarismo', 'O que conta é o efeito: dinheiro e plataforma a quem causa dano, contra o bem que a obra faz.'), ('etica-das-virtudes', 'Virtudes', 'O juízo fino de quando apreciar, quando calar e quando não aplaudir; nem rigidez, nem indiferença.'), ('deontologia-kantiana', 'Kant', 'A obra não é cúmplice; quem a financia sabendo que sustenta o dano, pode ser.'), ('particularismo', 'Particularismo', 'Não há regra geral: cada obra, cada autor e cada tipo de consumo pesam diferente.'), ('consequencialismo-de-regras', 'Consequencialismo de regras', 'Regras de instituições (prêmios, escolas) sobre quem celebrar têm efeitos de sinal que valem avaliar.')],
 licoes=['dilemas-do-cotidiano', 'responsabilidade-coletiva', 'emocoes-morais', 'como-discutir-etica'],
 fx=[('Ethical Criticism of Art (Internet Encyclopedia of Philosophy)', 'https://iep.utm.edu/art-eth/'), ('Drawing the Line: What to Do with the Work of Immoral Artists', 'https://www.google.com/search?tbm=bks&q=Erich+Hatala+Matthes+Drawing+the+Line'), ('Genetic fallacy (Wikipédia)', WE + 'Genetic_fallacy'), ('Monsters: A Fan’s Dilemma', 'https://www.google.com/search?tbm=bks&q=Claire+Dederer+Monsters+A+Fan%27s+Dilemma')]),
]
